yt-dlp --flat-playlist --dump-json "https://www.tiktok.com/@giaimathitruongck" 2>/dev/null | python3 -c "
import json, sys
videos = []
for line in sys.stdin:
    try:
        d = json.loads(line)
        videos.append({
            'title': d.get('title','')[:100],
            'view_count': d.get('view_count',0),
            'id': d.get('id','')
        })
    except: pass
print(f'Total videos found: {len(videos)}')
for v in videos[:20]:
    print(f\"  [{v['view_count']:>8} views] {v['title']}\")
" 2>/dev/null

